import{_ as a,o as d,c as o,a3 as n}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Set up Bedrock packs","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/bedrock-addon-manager/docs/setup.md"},"headers":[],"relativePath":"packages/bedrock-addon-manager/docs/setup.md","filePath":"packages/bedrock-addon-manager/docs/setup.md","lastUpdated":1791428389000}'),s={name:"packages/bedrock-addon-manager/docs/setup.md"};function r(t,e,c,i,l,p){return d(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="set-up-bedrock-packs" tabindex="-1">Set up Bedrock packs <a class="header-anchor" href="#set-up-bedrock-packs" aria-label="Permalink to &quot;Set up Bedrock packs&quot;">​</a></h1><h2 id="install-and-scan-packs" tabindex="-1">Install and scan packs <a class="header-anchor" href="#install-and-scan-packs" aria-label="Permalink to &quot;Install and scan packs&quot;">​</a></h2><ol><li>Put <code>bedrock-addon-manager.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> directory.</li><li>Start or restart the server and grant the requested data-folder and TCP-listener permissions in the server console.</li><li>Copy <code>.mcpack</code> or <code>.mcaddon</code> files into <code>plugins/data/BedrockAddonManager/packs/</code>.</li><li>Run <code>/baddon reload</code>, then <code>/baddon list</code> to inspect the packs and their effective settings.</li></ol><p>The folder is scanned at startup and on <code>/baddon reload</code>; new files are not detected automatically. The plugin creates and updates its own <code>config.toml</code> in its data folder. Changes apply after a reload or restart.</p><h2 id="choose-a-download-address" tabindex="-1">Choose a download address <a class="header-anchor" href="#choose-a-download-address" aria-label="Permalink to &quot;Choose a download address&quot;">​</a></h2><p>The plugin listens on the configured <code>web.bind</code> address and <code>web.port</code> (default <code>0.0.0.0:8123</code>). Bedrock clients need an address they can reach:</p><ul><li>Set <code>web.public_url</code> to the public base URL when a reverse proxy or external host serves the files. Do not add a trailing slash. The plugin&#39;s built-in server is plain HTTP; terminate HTTPS at the proxy.</li><li>Leave <code>web.public_url</code> empty to use UPnPumpkin port forwarding when <code>web.bind</code> is <code>0.0.0.0</code> and <code>web.port_forwarding</code> is enabled. This only works when the network permits router mapping and the host is not behind carrier-grade NAT.</li><li>Set <code>web.port_forwarding = false</code> when forwarding is managed manually.</li><li>If packs are hosted elsewhere, set <code>web.enabled = false</code> and provide a <code>download_url</code> override for every enabled pack.</li></ul><p>If forwarding is unavailable and no public URL is configured, the fallback address is loopback and only works for clients on the server machine.</p><h2 id="mcaddon-bundles-and-overrides" tabindex="-1"><code>.mcaddon</code> bundles and overrides <a class="header-anchor" href="#mcaddon-bundles-and-overrides" aria-label="Permalink to &quot;`.mcaddon` bundles and overrides&quot;">​</a></h2><p>The plugin extracts resource packs from bundles into <code>packs/.extracted/</code>. Behavior packs are left out. A single extracted pack is named after the <code>.mcaddon</code> file; multiple packs include the pack name. Use the exact effective filename shown by <code>/baddon list</code> as the key under <code>overrides</code>.</p><p>Overrides can change order, disable a pack, replace its download URL, or provide manifest values such as <code>content_key</code> and <code>content_id</code>. Packs sort by <code>order</code>, then filename. The server&#39;s <code>pumpkin.toml</code> is not edited.</p>',11)])])}const k=a(s,[["render",r]]);export{u as __pageData,k as default};
